package org.humanjourney.core.mapfeature;
import java.util.*;
import org.humanjourney.core.geography.map.MapArea.Bounds;
/** Per-component immutable BVH: distant components never force a giant feature candidate box. */
public final class FeatureIndex {
 public record PartEntry(MapFeature.View feature,int partIndex,Bounds bounds){public boolean line(){return partIndex<0;}public boolean contains(double x,double z){return !line()&&feature.geometry().parts().get(partIndex).contains(x,z);}public boolean near(double x,double z,double radius){return line()?feature.geometry().distanceSquared(x,z)<=radius*radius:feature.geometry().parts().get(partIndex).near(x,z,radius);}}
 private final Map<String,Node> roots=new HashMap<>();
 private static final class Node{final Bounds bounds;final Node left,right;final List<PartEntry> leaf;Node(List<PartEntry> list){Bounds b=list.getFirst().bounds();for(var e:list)b=b.union(e.bounds());bounds=b;if(list.size()<=12){leaf=List.copyOf(list);left=right=null;}else{var copy=new ArrayList<>(list);boolean x=b.maxX()-b.minX()>=b.maxZ()-b.minZ();copy.sort(Comparator.comparingDouble(e->x?e.bounds().minX()+e.bounds().maxX():e.bounds().minZ()+e.bounds().maxZ()));int m=copy.size()/2;left=new Node(copy.subList(0,m));right=new Node(copy.subList(m,copy.size()));leaf=null;}}void query(Bounds b,List<PartEntry> out){if(!bounds.intersects(b))return;if(leaf!=null){for(var e:leaf)if(e.bounds().intersects(b))out.add(e);}else{left.query(b,out);right.query(b,out);}}}
 public record Selection(MapFeature.View feature,int candidates,boolean ambiguous,int partIndex){public Selection(MapFeature.View f,int c,boolean a){this(f,c,a,-1);}}
 public FeatureIndex(Collection<MapFeature.View> features){GeometryBudget.check(features);Map<String,List<PartEntry>> groups=new HashMap<>();for(var f:features){var list=groups.computeIfAbsent(f.dimension(),k->new ArrayList<>());if(f.geometry().kind()==FeatureGeometry.Kind.POLYLINE)list.add(new PartEntry(f,-1,f.geometry().bounds()));else for(int i=0;i<f.geometry().parts().size();i++)list.add(new PartEntry(f,i,f.geometry().parts().get(i).bounds()));}groups.forEach((d,v)->roots.put(d,new Node(v)));}
 public List<PartEntry> queryParts(String dimension,Bounds box){var out=new ArrayList<PartEntry>();var root=roots.get(dimension);if(root!=null)root.query(box,out);return out;}
 public List<MapFeature.View> query(String dimension,Bounds box){var out=new TreeMap<String,MapFeature.View>();for(var e:queryParts(dimension,box))out.put(e.feature().id(),e.feature());return new ArrayList<>(out.values());}
 public static Bounds around(double x,double z,double radius){return new Bounds(x-radius,z-radius,x+radius,z+radius);}
 public Selection hover(String dimension,double x,double z,double lineTolerance){if(!Double.isFinite(x)||!Double.isFinite(z)||!Double.isFinite(lineTolerance)||lineTolerance<0||Math.abs(x)>30000000||Math.abs(z)>30000000)return new Selection(null,0,false);var candidates=queryParts(dimension,around(x,z,lineTolerance));var lines=new TreeMap<String,PartEntry>();var polygons=new TreeMap<String,PartEntry>();for(var entry:candidates){if(entry.line()){if(entry.near(x,z,lineTolerance))lines.put(entry.feature().id(),entry);}else if(entry.contains(x,z))polygons.merge(entry.feature().id(),entry,(a,b)->a.partIndex()<b.partIndex()?a:b);}var matching=lines.isEmpty()?polygons:lines;PartEntry best=null;boolean tie=false;for(var entry:matching.values()){if(best==null||entry.feature().priority()>best.feature().priority()){best=entry;tie=false;}else if(entry.feature().priority()==best.feature().priority())tie=true;}return new Selection(tie||best==null?null:best.feature(),candidates.size(),tie,tie||best==null?-1:best.partIndex());}
}
